31	+package spoon.reflect.visitor;
32	+
33	+import spoon.reflect.code.CtCatch;
34	+import spoon.reflect.code.CtFor;
35	+import spoon.reflect.code.CtForEach;
36	+import spoon.reflect.code.CtLocalVariable;
37	+import spoon.reflect.code.CtStatement;
38	+import spoon.reflect.code.CtStatementList;
39	+import spoon.reflect.code.CtTryWithResource;
40	+import spoon.reflect.declaration.CtElement;
41	+import spoon.reflect.declaration.CtExecutable;
42	+import spoon.reflect.declaration.CtField;
43	+import spoon.reflect.declaration.CtMethod;
44	+import spoon.reflect.declaration.CtPackage;
45	+import spoon.reflect.declaration.CtType;
46	+import spoon.reflect.declaration.CtVariable;
47	+import spoon.reflect.declaration.ModifierKind;
48	+import spoon.reflect.reference.CtTypeReference;
49	+
50	+import java.util.ArrayList;
51	+import java.util.Collections;
52	+import java.util.Iterator;
53	+import java.util.List;
54	+import java.util.Set;
55	+
56	+/**
57	+ * Find local variables catch, parameters, fields, super fields
58	+ * @author tdurieux
59	+ */
60	+public class AccessibleVariablesFinder {
61	+
62	+	private CtElement expression;
63	+
64	+	public AccessibleVariablesFinder(CtElement expression) {
65	+		this.expression = expression;
66	+	}
67	+
68	+	public List<CtVariable> find() {
69	+		if (expression.isParentInitialized()) {
70	+			return getVariable(expression.getParent());
71	+		}
72	+		return Collections.emptyList();
73	+	}
74	+
75	+	private List<CtVariable> getVariable(final CtElement parent) {
76	+		final List<CtVariable> variables = new ArrayList<>();
77	+		if (parent == null) {
78	+			return variables;
79	+		}
80	+		class VariableScanner extends CtInheritanceScanner {
81	+			@Override
82	+			public void visitCtStatementList(CtStatementList e) {
83	+				for (int i = 0; i < e.getStatements().size(); i++) {
84	+					CtStatement ctStatement = e.getStatements().get(i);
85	+					if (ctStatement.getPosition() == null) {
86	+					}
87	+					if (ctStatement.getPosition() != null
88	+							&& ctStatement.getPosition().getSourceStart() > expression.getPosition().getSourceEnd()) {
89	+						break;
90	+					}
91	+					if (ctStatement instanceof CtVariable) {
92	+						variables.add((CtVariable) ctStatement);
93	+					}
94	+				}
95	+				super.visitCtStatementList(e);
96	+			}
97	+
98	+			@Override
99	+			public <T> void scanCtType(CtType<T> type) {
100	+				List<CtField<?>> fields = type.getFields();
101	+				for (int i = 0; i < fields.size(); i++) {
102	+					CtField<?> ctField = fields.get(i);
103	+					if (ctField.hasModifier(ModifierKind.PUBLIC) || ctField.hasModifier(ModifierKind.PROTECTED)) {
104	+						variables.add(ctField);
105	+					} else if (ctField.hasModifier(ModifierKind.PRIVATE)) {
106	+						if (expression.hasParent(type)) {
107	+							variables.add(ctField);
108	+						}
109	+					} else if (expression.getParent(CtPackage.class).equals(type.getParent(CtPackage.class))) {
110	+						// default visibility
111	+						variables.add(ctField);
112	+					}
113	+				}
114	+				CtTypeReference<?> superclass = type.getSuperclass();
115	+				if (superclass != null) {
116	+					variables.addAll(getVariable(superclass.getTypeDeclaration()));
117	+				}
118	+				Set<CtTypeReference<?>> superInterfaces = type.getSuperInterfaces();
119	+				for (Iterator<CtTypeReference<?>> iterator = superInterfaces.iterator(); iterator.hasNext();) {
120	+					CtTypeReference<?> typeReference = iterator.next();
121	+					variables.addAll(getVariable(typeReference.getTypeDeclaration()));
122	+				}
123	+				super.scanCtType(type);
124	+			}
125	+
126	+			@Override
127	+			public void visitCtTryWithResource(CtTryWithResource e) {
128	+				variables.addAll(e.getResources());
129	+				super.visitCtTryWithResource(e);
130	+			}
131	+
132	+			@Override
133	+			public void scanCtExecutable(CtExecutable e) {
134	+				variables.addAll(e.getParameters());
135	+				super.scanCtExecutable(e);
136	+			}
137	+
138	+			@Override
139	+			public void visitCtFor(CtFor e) {
140	+				for (CtStatement ctStatement : e.getForInit()) {
141	+					this.scan(ctStatement);
142	+				}
143	+				super.visitCtFor(e);
144	+			}
145	+
146	+			@Override
147	+			public void visitCtForEach(CtForEach e) {
148	+				variables.add(e.getVariable());
149	+				super.visitCtForEach(e);
150	+			}
151	+
152	+			@Override
153	+			public void visitCtMethod(CtMethod e) {
154	+				this.scan(e.getBody());
155	+				super.visitCtMethod(e);
156	+			}
157	+
158	+			@Override
159	+			public void visitCtLocalVariable(CtLocalVariable e) {
160	+				variables.add(e);
161	+				super.visitCtLocalVariable(e);
162	+			}
163	+
164	+			@Override
165	+			public void visitCtCatch(CtCatch e) {
166	+				variables.add(e.getParameter());
167	+
168	+				super.visitCtCatch(e);
169	+			}
170	+		}
171	+
172	+		new VariableScanner().scan(parent);
173	+
174	+		return variables;
175	+	}
176	+}
