191	+
192	+	/**
193	+	 * Test if the reference should be imported by looking if there is a name conflict
194	+	 * @param ref
195	+	 * @return true if the ref should be imported.
196	+	 */
197	+	private boolean shouldTypeBeImported(CtTypeReference<?> ref) {
198	+		// we import the targetType by default to simplify and avoid conclict in inner classes
199	+		if (ref.equals(targetType)) {
200	+			return true;
201	+		}
202	+
203	+		try {
204	+			CtElement parent = ref.getParent();
205	+
206	+			if (parent instanceof CtNamedElement) {
207	+				namedElements.add(((CtNamedElement) parent).getSimpleName());
208	+			}
209	+
210	+			while (!(parent instanceof CtPackage)) {
211	+				if (parent instanceof CtFieldReference) {
212	+					CtFieldReference parentType = (CtFieldReference) parent;
213	+					Set<String> qualifiedNameTokens = new HashSet<>();
214	+
215	+					qualifiedNameTokens.add(parentType.getSimpleName());
216	+
217	+					CtTypeReference typeReference = parentType.getDeclaringType();
218	+
219	+					qualifiedNameTokens.add(typeReference.getSimpleName());
220	+
221	+					if (typeReference.getPackage() != null) {
222	+						CtPackage ctPackage = typeReference.getPackage().getDeclaration();
223	+
224	+						while (ctPackage != null) {
225	+							qualifiedNameTokens.add(ctPackage.getSimpleName());
226	+
227	+							CtElement packParent = ctPackage.getParent();
228	+							if (packParent.getParent() != null) {
229	+								ctPackage = (CtPackage) packParent;
230	+							} else {
231	+								ctPackage = null;
232	+							}
233	+						}
234	+
235	+						for (String token : qualifiedNameTokens) {
236	+							if (namedElements.contains(token)) {
237	+								return true;
238	+							}
239	+						}
240	+					}
241	+				}
242	+				parent = parent.getParent();
243	+			}
244	+		} catch (ParentNotInitializedException e) {
245	+			return false;
246	+		}
247	+
248	+		return false;
249	+	}
